// Полный парсер для всех исторических рецептов (водки + ликёры)
console.log('=== ПАРСИНГ ВСЕХ РЕЦЕПТОВ (ВОДКИ + ЛИКЁРЫ) ===');

try {
  const inputData = $input.first();

  if (!inputData?.json?.content) {
    return [{ json: { error: 'No content field found' } }];
  }

  const fullText = inputData.json.content;
  console.log(`Полный текст: ${fullText.length} символов`);

  function parseAllHistoricalRecipes(text) {
    const recipes = [];

    console.log('Начинаем парсинг всех исторических рецептов...');

    try {
      // Ищем рецепты водок (паттерн **номер. название**)
      const vodkaPattern = /\*\*(\d+)\.\s*([^*\n]+?)\*\*([\s\S]*?)(?=\*\*\d+\.|$)/g;
      let match;
      let foundVodkaCount = 0;

      console.log('Ищем рецепты водок...');
      while ((match = vodkaPattern.exec(text)) !== null) {
        const number = parseInt(match[1]);
        const name = match[2].trim().replace(/\.$/, '');
        let content = match[3].trim();

        content = content.replace(/^\s*\n+/, '');

        const isChapterHeader = name.includes('ГЛАВА') || 
                               name.includes('§') || 
                               content.length < 50;

        if (!isChapterHeader && name.length > 3 && content.length > 30) {
          recipes.push({
            id: `recipe_${number}`,
            number: number,
            name: name,
            content: content,
            full_text: `${name}\n\n${content}`,
            source_pattern: 'starred_number_title',
            category: 'водка'
          });

          foundVodkaCount++;
          if (foundVodkaCount <= 5) {
            console.log(`  Водка ${number}: "${name}" (${content.length} символов)`);
          }
        }
      }

      console.log(`Найдено ${foundVodkaCount} рецептов водок`);

      // Теперь ищем ликёры
      console.log('Ищем рецепты ликёров...');
      let nextRecipeNumber = Math.max(...recipes.map(r => r.number), 209) + 1;
      let foundLiqueurCount = 0;

      const liqueurPattern1 = /\*\*(\d+)\)\s*([^*]+?)\.\*\*\s*([\s\S]*?)(?=\*\*\d+[.\))]|§\s*\d+\.|$)/g;
      let match1;

      while ((match1 = liqueurPattern1.exec(text)) !== null) {
        const origNumber = parseInt(match1[1]);
        let name = match1[2].trim();
        let content = match1[3].trim();

        const hasIngredients = content.match(/(?:Возьмите|Состав|Набор):/i);

        if (hasIngredients && content.length > 50) {
          name = name.replace(/^Ликёр\s*/i, '');

          recipes.push({
            id: `recipe_${nextRecipeNumber}`,
            number: nextRecipeNumber,
            name: `Ликёр ${name}`,
            content: content,
            full_text: `Ликёр ${name}\n\n${content}`,
            source_pattern: 'paragraph_liqueur',
            category: 'ликёр',
            original_number: origNumber
          });

          foundLiqueurCount++;
          if (foundLiqueurCount <= 10) {
            console.log(`  Ликёр ${nextRecipeNumber}: "${name}"`);
          }
          nextRecipeNumber++;
        }
      }

      const liqueurPattern2 = /\*\*(\d+)\.\s*([^*]+?)\.\*\*\s*([\s\S]*?)(?=\*\*\d+[.\))]|§\s*\d+\.|$)/g;
      let match2;

      while ((match2 = liqueurPattern2.exec(text)) !== null) {
        const origNumber = parseInt(match2[1]);
        let name = match2[2].trim();
        let content = match2[3].trim();

        if (recipes.find(r => r.original_number === origNumber)) {
          continue;
        }

        const hasIngredients = content.match(/(?:Возьмите|Состав|Набор):/i);

        if (hasIngredients && content.length > 50 && name.toLowerCase().includes('ликёр')) {
          name = name.replace(/^Ликёр\s*/i, '');

          recipes.push({
            id: `recipe_${nextRecipeNumber}`,
            number: nextRecipeNumber,
            name: `Ликёр ${name}`,
            content: content,
            full_text: `Ликёр ${name}\n\n${content}`,
            source_pattern: 'liqueur_dot_pattern',
            category: 'ликёр',
            original_number: origNumber
          });

          foundLiqueurCount++;
          if (foundLiqueurCount <= 10) {
            console.log(`  Ликёр ${nextRecipeNumber}: "${name}"`);
          }
          nextRecipeNumber++;
        }
      }

      console.log(`Найдено ${foundLiqueurCount} рецептов ликёров`);

      // Дополнительный поиск для оставшихся рецептов водок
      if (foundVodkaCount < 200) {
        console.log('Ищем дополнительные рецепты водок...');

        const lines = text.split('\n');
        let currentRecipe = null;
        let recipeContent = [];
        let additionalVodkaCount = 0;

        for (let i = 0; i < lines.length; i++) {
          const line = lines[i].trim();

          const numberMatch = line.match(/^(\d+)\.\s*(.+?)\.?\s*$/);

          if (numberMatch) {
            const number = parseInt(numberMatch[1]);
            const name = numberMatch[2].trim();

            if (currentRecipe && recipeContent.length > 0) {
              const content = recipeContent.join('\n').trim();
              if (content.length > 50 && !recipes.some(r => r.number === currentRecipe.number)) {
                const category = content.toLowerCase().includes('ликёр') || 
                               currentRecipe.name.toLowerCase().includes('ликёр') ? 'ликёр' : 'водка';

                if (category === 'водка') {
                  recipes.push({
                    id: `recipe_${currentRecipe.number}`,
                    number: currentRecipe.number,
                    name: currentRecipe.name,
                    content: content,
                    full_text: `${currentRecipe.name}\n\n${content}`,
                    source_pattern: 'plain_number_title',
                    category: category
                  });

                  additionalVodkaCount++;
                  if (additionalVodkaCount <= 5) {
                    console.log(`  Доп. водка ${currentRecipe.number}: "${currentRecipe.name}"`);
                  }
                }
              }
            }

            if (number >= 1 && number <= 350 && name.length > 3) {
              currentRecipe = {
                number: number,
                name: name
              };
              recipeContent = [];
            } else {
              currentRecipe = null;
            }

          } else if (currentRecipe && line.length > 0) {
            recipeContent.push(line);
          }
        }

        if (currentRecipe && recipeContent.length > 0) {
          const content = recipeContent.join('\n').trim();
          if (content.length > 50 && !recipes.some(r => r.number === currentRecipe.number)) {
            const category = content.toLowerCase().includes('ликёр') || 
                           currentRecipe.name.toLowerCase().includes('ликёр') ? 'ликёр' : 'водка';

            if (category === 'водка') {
              recipes.push({
                id: `recipe_${currentRecipe.number}`,
                number: currentRecipe.number,
                name: currentRecipe.name,
                content: content,
                full_text: `${currentRecipe.name}\n\n${content}`,
                source_pattern: 'plain_number_title',
                category: category
              });
            }
          }
        }

        console.log(`Найдено дополнительно ${additionalVodkaCount} рецептов водок`);
      }

    } catch (parseError) {
      console.log('Ошибка парсинга:', parseError.message);
    }

    return recipes;
  }

  // Парсим все рецепты
  const allRecipes = parseAllHistoricalRecipes(fullText);
  console.log(`НАЙДЕНО РЕЦЕПТОВ: ${allRecipes.length}`);

  if (allRecipes.length === 0) {
    console.log('=== НЕ НАЙДЕНО РЕЦЕПТОВ ===');
    return [{ json: { 
      error: 'No recipes found',
      document_length: fullText.length,
      text_sample: fullText.substring(0, 2000)
    }}];
  }

  allRecipes.sort((a, b) => a.number - b.number);

  console.log('=== ПАРСИНГ ЗАВЕРШЕН ===');
  console.log(`Обработано рецептов: ${allRecipes.length}`);

  return allRecipes.map(recipe => ({ json: recipe }));

} catch (globalError) {
  console.log('КРИТИЧЕСКАЯ ОШИБКА:', globalError.message);
  return [{ json: { 
    error: 'Critical parsing error',
    message: globalError.message,
    stack: globalError.stack
  }}];
}

// Code1: Подготовка текста для BGE-M3 embed/qdrant
const recipe = $input.first().json;

const fullText = `Рецепт: ${recipe.name}\n\nСодержание: ${recipe.content}`;

// BGE-M3 поддерживает до 8192 токенов — лимит больше чем у OpenAI
const MAX_CHARS = 16000;
let embeddingText = fullText;

if (fullText.length > MAX_CHARS) {
  const truncated = fullText.substring(0, MAX_CHARS);
  const lastSpace = truncated.lastIndexOf(' ');
  embeddingText = lastSpace > MAX_CHARS * 0.9
    ? truncated.substring(0, lastSpace) + '...'
    : truncated + '...';
  console.log(`Текст обрезан: ${fullText.length} → ${embeddingText.length} символов`);
}

return [{
  json: {
    embed_text: embeddingText,
    recipe_data: {
      id: recipe.id,
      number: recipe.number,
      name: recipe.name,
      content: recipe.content,
      full_text: recipe.full_text,
      category: recipe.category || ''
    }
  }
}];

// Combining vectors: BGE-M3 dense + sparse → Qdrant point
const response = $input.last().json;
const recipe = $('Code1').first().json.recipe_data;

// Извлекаем dense и sparse из ответа /embed/qdrant
const dense = response.results[0].dense;
const sparse = response.results[0].sparse;

console.log(`Рецепт: ${recipe.name}`);
console.log(`Dense: ${dense.length} dims, Sparse: ${sparse.indices.length} tokens`);

const point = {
  id: Math.abs(recipe.number * 10000 + Date.now() % 10000),
  vector: {
    dense: dense,
    sparse: sparse
  },
  payload: {
    recipe_id: recipe.id,
    recipe_number: recipe.number,
    recipe_name: recipe.name,
    content: recipe.content,
    full_text: recipe.full_text,
    category: recipe.category || '',
    content_length: recipe.content?.length || 0,
    name_lower: recipe.name?.toLowerCase() || '',
    is_vodka: (recipe.category === 'водка') || false,
    is_liqueur: (recipe.category === 'ликёр') || false,
    created_at: new Date().toISOString(),
    vector_dimension: dense.length,
    sparse_token_count: sparse.indices.length
  }
};

console.log(`✅ Point создан: ID=${point.id}, рецепт "${recipe.name}"`);

return [{ json: { points: [point] } }];
